var t=[{title:`Basisanatomie`,text:`De wervelkolom heeft een cervicaal, thoracaal, lumbaal, sacraal en coccygeaal gedeelte. De natuurlijke krommingen verschillen per persoon en veranderen met de positie. Bij veel beladen tilbewegingen is je wervelkolom beheerst en dicht bij je eigen comfortabele neutrale bereik houden een nuttige beginstrategie, vooral terwijl je nog aan het leren bent.`},{title:`Wat de „core” omvat`,text:`De buikspieren, schuine buikspieren, diepere rompspieren, rugstrekkers, het middenrif en de bekkenbodemspieren werken samen om druk en beweging te regelen. Ze buigen de romp, en ze weerstaan ook ongewenste strekking, rotatie of zijwaartse buiging terwijl kracht tussen je armen en benen wordt doorgegeven.`},{title:`Aanspannen en intrekken`,text:`Aanspannen (bracing) betekent meestal spanning rondom je romp opbouwen, alsof je je voorbereidt op een lichte duw in je buik, terwijl je je ademhaling onder controle houdt. Intrekken (hollowing) richt zich op het naar binnen trekken van de buikwand. Beide kunnen nut hebben, maar het zijn verschillende instructies. Bij zwaar tillen helpt gecoördineerd aanspannen meestal meer dan alleen je buik intrekken.`},{title:`Intra-abdominale druk`,text:`Je middenrif en buikwand kunnen interne druk opbouwen die de romp helpt te verstijven. De exacte ademhalingsstrategie hangt af van het gewicht en je ervaring. Lang, intensief je adem inhouden past mogelijk niet bij mensen met bepaalde hart- en vaatproblemen, dus vraag je arts om advies als dat voor jou geldt.`},{title:`Voorbeeld`,text:`Ga voor een matige goblet squat rechtop staan, adem comfortabel in, span je romp aan, zak gecontroleerd en adem uit bij de zware weg omhoog als dat nodig is. Houd bij een suitcase carry je romp rechtop en laat het gewicht je niet zijwaarts trekken.`},{title:`De core trainen`,text:`Corewerk omvat planks, dead bugs, carries en de hoofdbewegingspatronen, naast sit-ups. Geen enkele wervelkolompositie is voor iedereen veilig, en aanspannen compenseert niet voor het kiezen van een onverstandig gewicht.`}];var a=[{label:`Standpunt van het ACSM uit 2026`,url:`https://pubmed.ncbi.nlm.nih.gov/41843416/`},{label:`CDC-richtlijnen voor lichaamsbeweging`,url:`https://www.cdc.gov/healthy-weight-growth/physical-activity/getting-started.html`}];var i={sections:t,sources:a};export{i as default,t as sections,a as sources};